package com.bank.bdaygroup;

import java.time.*;
import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class SharedMonthDemo {
    private static final Logger log = Logger.getLogger("BdayGroup");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", LocalDate.parse("1990-06-20")),
            new Employee("Amit", LocalDate.parse("1995-06-05")),    // June shared
            new Employee("Priya", LocalDate.parse("1988-03-01")));
        BirthdayGroupService service = new BirthdayGroupService();

        Map<Month, List<String>> shared = service.sharedBirthdayMonths(staff);
        shared.forEach((m, names) -> log.info(() -> m + " → " + names));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final LocalDate dob;
        Employee(String name, LocalDate dob) { this.name = name;
        this.dob = dob; }
    String getName() { return name; }
    LocalDate getDob() { return dob; }
}

// ─── Would be in service/BirthdayGroupService.java ───
class BirthdayGroupService {
    Map<Month, List<String>> sharedBirthdayMonths(List<Employee> staff) {
        Map<Month, List<String>> byMonth = staff.stream()
            .filter(e -> e.getDob() != null)
            .collect(groupingBy(e -> e.getDob().getMonth(),
                mapping(Employee::getName, toList())));
        return byMonth.entrySet().stream()
            .filter(e -> e.getValue().size() > 1)          // keep only shared months
            .collect(toMap(Map.Entry::getKey, Map.Entry::getValue));
    }
}
